        gsMatrix<T> & solVector = *_Sv;
        const gsDofMapper & mapper = _u.mapper();

        index_t patchStart, patchEnd; 
        if (patch==-1){
            patchStart = 0; 
            patchEnd   = _u.mapper().numPatches();
        }
        else{
            patchStart = patch;
            patchEnd   = patch + 1;
        }

