template <class T>
T gsTriMeshToSolid<T>::calcArea(FaceHandle f1)
{
    T d1=calcDist(f1->vertices[0],f1->vertices[1]);
    T d2=calcDist(f1->vertices[0],f1->vertices[2]);
    T d3=calcDist(f1->vertices[1],f1->vertices[2]);
    //p=perimeter/2
    T p=(d1+d2+d3)/T(2.0);
    T area=math::sqrt(p*(p-d1)*(p-d2)*(p-d3));
    return area;
}

