                               gsFuncData<T> & out   ) const
{
    const unsigned flags = out.flags;

    out.info = info();
    evalAllDers_into(in, out.maxDeriv(), out.values);

    if (flags & NEED_ACTIVE && flags & SAME_ELEMENT)
        active_into(in.col(0), out.actives);
