                gsDebug << "P="<<patchIndex <<"\n "<< it->second.mine().values[0] <<"\n"
                << "Params : " << m_points.mine() << "\n"
                << "Patch: " << it->first->function(patchIndex) << "\n";
            }
        }

        for (FuncDataIt it = m_fdata.begin(); it != m_fdata.end(); ++it)
