 template<unsigned d, class Basis_t >
 inline unsigned gsTensorBasis<d,Basis_t>::index(gsVector<unsigned,d> const & v) const
 {
     unsigned ind;

     ind = v(d-1) ;//compute global index in the tensor product
     for ( int i=d-2; i>=0; --i )
         ind = ind * size(i) + v(i) ;
     return ind;
 }

